export const ADMIN_FILES = [{"id":"launch","title":"North Hollywood launch plan","summary":"Readiness, what to do before the first sale, the 30-day plan and who to pitch first.","icon":"bolt","updated":"2026-10-09","html":"<p class=\"lead\">CityPulse can start selling North Hollywood ads now. The kiosk, dashboard, website and checkout all passed a live check on Oct 9. The tasks below save as you tick them, so everyone signed in sees the same progress.</p>\n\n<h2>Readiness</h2>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>Area</th><th>Status</th><th>Live check</th></tr></thead>\n<tbody>\n<tr><td>Lobby kiosk (lexen-lobby)</td><td><span class=\"pill ok\"><i></i>Ready</span></td><td>Online, version 17</td></tr>\n<tr><td>Guest kiosk screen</td><td><span class=\"pill ok\"><i></i>Ready</span></td><td>Live weather, 3 ads rotating, AI concierge answering</td></tr>\n<tr><td>Owner dashboard</td><td><span class=\"pill ok\"><i></i>Ready</span></td><td>Signed in, database connected, every section working</td></tr>\n<tr><td>Website</td><td><span class=\"pill ok\"><i></i>Ready</span></td><td>205 pages, 0 broken links, 0 script errors</td></tr>\n<tr><td>Checkout and e-signature</td><td><span class=\"pill ok\"><i></i>Ready</span></td><td>Test order delivered with order number and signature</td></tr>\n<tr><td>Online payment</td><td><span class=\"pill warn\"><i></i>Not connected</span></td><td>Stripe links are blank, so checkout says \"Place my order\" and you invoice</td></tr>\n<tr><td>Order email delivery</td><td><span class=\"pill warn\"><i></i>Check once</span></td><td>FormSubmit needs a one-time Activate click in sarvesh.joshiaz@gmail.com</td></tr>\n<tr><td>sales@citypulsekiosks.com</td><td><span class=\"pill warn\"><i></i>Not set up</span></td><td>The Terms, checkout and error messages send people to this address</td></tr>\n</tbody></table></div>\n\n<div class=\"callout\"><b>Your call:</b> Granville, El Portal Theatre and NoHo Diner already show on the kiosk as \"Sponsored\" at no charge. Decide whether they convert to paid, stay as free launch partners, or come down to make room for paying advertisers.</div>\n\n<h2>Today</h2>\n<div class=\"tasks\">\n<label class=\"task\"><input type=\"checkbox\" data-task=\"stripe-links\"><span>Create two Stripe Payment Links ($399 a year and $60 a month, one location) and send them to be connected. Until then, invoice by hand.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"formsubmit-activate\"><span>Place one test order on the website and click <b>Activate</b> in the FormSubmit email, so real orders reach the inbox.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"sales-inbox\"><span>Set up sales@citypulsekiosks.com, or point the site at Gmail for now.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"free-sponsors\"><span>Decide what happens to the three free \"Sponsored\" ads.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"remove-preview\"><span>Delete the \"preview\" entry in Kiosks; it is a test browser, not a screen.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"walk-five\"><span>Walk the five closest businesses with the kiosk open on your phone (list below).</span></label>\n</div>\n\n<h2>First week, Oct 10&ndash;16</h2>\n<div class=\"tasks\">\n<label class=\"task\"><input type=\"checkbox\" data-task=\"attorney-review\"><span>Attorney review of the Terms and Advertiser Agreement, including the three-year initial term.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"hotel-numbers\"><span>Ask the hotel for room count and average occupancy, so the pitch can quote real guest volume.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"visit-fifteen\"><span>Visit all 15 walkable businesses below; leave the pricing page and your number.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"first-three\"><span>Close the first 3 paying advertisers and send each their live report link.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"advertise-notice\"><span>Post an \"Advertise here\" announcement on the kiosk pointing to the pricing page.</span></label>\n</div>\n\n<h2>Days 8&ndash;30, through Nov 8</h2>\n<div class=\"tasks\">\n<label class=\"task\"><input type=\"checkbox\" data-task=\"eight-advertisers\"><span>Reach 8 paying advertisers, then start a waitlist.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"week-checkins\"><span>Send each advertiser a one-week check-in with their report.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"real-numbers\"><span>Swap test numbers in the pitch for a full week of real guest numbers.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"domain\"><span>Connect citypulsekiosks.com to the website.</span></label>\n<label class=\"task\"><input type=\"checkbox\" data-task=\"next-venue\"><span>Pick the next North Hollywood host venue using what sold best here.</span></label>\n</div>\n\n<h2>The goal</h2>\n<p>8 paying advertisers on the lobby screen in the first 30 days: $480 a month on monthly plans, or $3,192 a year if all pay yearly. Ads rotate every 8 seconds, so with 8 ads each one shows about once a minute. Eight is the comfortable limit for one screen, which makes the early sales a scarcity pitch: \"8 spots, first come.\"</p>\n\n<h2>Who to pitch first</h2>\n<p>By walking time from the lobby, from the kiosk's own place list.</p>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>Business</th><th>What it is</th><th class=\"num\">Walk</th></tr></thead>\n<tbody>\n<tr><td>North Hollywood Diner</td><td>Breakfast and diner classics</td><td class=\"num\">3 min</td></tr>\n<tr><td>Amp Coffee LA</td><td>Coffee shop</td><td class=\"num\">4 min</td></tr>\n<tr><td>El Portal Theatre</td><td>Live theatre (now a free sponsor)</td><td class=\"num\">4 min</td></tr>\n<tr><td>NoHo Pizza</td><td>Pizza, takeout and delivery</td><td class=\"num\">4 min</td></tr>\n<tr><td>Smash N Stacked Burger</td><td>Burgers</td><td class=\"num\">4 min</td></tr>\n<tr><td>Horror Vibes Coffee</td><td>Themed coffee shop</td><td class=\"num\">5 min</td></tr>\n<tr><td>Moxie Coffee Bar</td><td>Coffee bar</td><td class=\"num\">5 min</td></tr>\n<tr><td>City Kitchen</td><td>Breakfast, salads and coffee</td><td class=\"num\">6 min</td></tr>\n<tr><td>The Moon Caf&eacute;</td><td>Coffee, tea and Mediterranean food</td><td class=\"num\">6 min</td></tr>\n<tr><td>Eggspresso Muffins</td><td>Brunch, coffee and sandwiches</td><td class=\"num\">8 min</td></tr>\n<tr><td>Exer Urgent Care</td><td>Urgent care</td><td class=\"num\">8 min</td></tr>\n<tr><td>Granville</td><td>American restaurant and bar (now a free sponsor)</td><td class=\"num\">8 min</td></tr>\n<tr><td>Maki-Noho</td><td>Japanese and sushi</td><td class=\"num\">10 min</td></tr>\n<tr><td>Lankershim Food Mart</td><td>Convenience store</td><td class=\"num\">12 min</td></tr>\n<tr><td>MexiSlice</td><td>Pizza</td><td class=\"num\">17 min</td></tr>\n</tbody></table></div>\n\n<h2>The pitch in three lines</h2>\n<ol>\n<li>Your logo and QR code in front of every guest who uses the lobby concierge.</li>\n<li>A live report of who saw it and who scanned it, any time, no sign-in.</li>\n<li>$60 a month or $399 a year for this location.</li>\n</ol>\n"},{"id":"selling","title":"Selling and running an ad","summary":"From first pitch to ad live on the kiosk to the monthly report, step by step.","icon":"ads","updated":"2026-10-09","html":"<p class=\"lead\">An ad goes from signed order to live on the kiosk in about 15 minutes of your time. Each ad shows for 8 seconds in turn with the business logo, name, walking time, tagline, website and a QR code.</p>\n\n<ol class=\"steps\">\n<li><b>Pitch.</b> Show the business the kiosk in person, or open the <a href=\"https://aeroassistindustries.github.io/spotlight-kiosks/kiosk-app/\" target=\"_blank\" rel=\"noopener\">kiosk link</a> on your phone. Leave the <a href=\"https://aeroassistindustries.github.io/spotlight-kiosks/pricing/\" target=\"_blank\" rel=\"noopener\">pricing page</a>: $399 a year or $60 a month for one location.</li>\n<li><b>Order.</b> The customer orders at the <a href=\"https://aeroassistindustries.github.io/spotlight-kiosks/#get-started\" target=\"_blank\" rel=\"noopener\">website checkout</a>: city Los Angeles, CA; business and contact details; logo or artwork, or \"Design it for me\"; then signs the Advertiser Agreement. You can fill it in with them on the spot.</li>\n<li><b>Payment.</b> Once the Stripe links are connected, checkout sends them to pay. Until then, invoice them; the order email says \"Invoice the customer\".</li>\n<li><b>Order email.</b> It arrives at sarvesh.joshiaz@gmail.com with an order number (CP-&hellip;), their details, signature and files attached.</li>\n<li><b>Add the ad.</b> Ads &rarr; Add an ad. Fill in business name, what it is, tagline (110 characters), website, QR link (starts with https://) and linked place, which adds the walking time. Upload the logo, set campaign start and end dates, and turn on Show on kiosks.</li>\n<li><b>Record the deal.</b> Open Deal details under the ad: contact, monthly price and status. It stays private and feeds the revenue total on Overview.</li>\n<li><b>Publish.</b> Check the live preview beside the ad, then click Publish to kiosks. The ad is on the lobby screen within about 2 minutes.</li>\n<li><b>Send their report link.</b> Advertiser report &rarr; Copy live link, and email it to them. It shows guests reached, views with a guest present and QR scans, updated live, with no sign-in.</li>\n<li><b>Every month.</b> Print or save the report as a PDF for the check-in. Next best actions on Overview flags ads about to end, so you can talk renewal.</li>\n</ol>\n\n<h2>What advertisers get</h2>\n<ul>\n<li>Their ad in rotation on the lobby screen, all day, every day.</li>\n<li>A QR code that opens their website or directions on the guest's phone, with every scan counted.</li>\n<li>A sponsored stop in \"Plan my evening\" when they are close by, labeled Sponsored.</li>\n<li>When they are listed under Places, the AI concierge can recommend them to guests.</li>\n<li>A live report link and a monthly PDF.</li>\n</ul>\n\n<h2>Keeping the screen sellable</h2>\n<p>Ads rotate in order, so more advertisers means each one comes around less often. With 8 ads each shows about once a minute. Hold the line at 8 per screen and start a waitlist after that.</p>\n"},{"id":"system","title":"How CityPulse works","summary":"A chart of the whole system, what happens step by step, and every outside service.","icon":"overview","updated":"2026-10-09","html":"<p class=\"lead\">Everything a guest, you or an advertiser does passes through one Cloudflare worker, which keeps all content and numbers in one database.</p>\n<div class=\"diagram-wrap\"><svg class=\"diagram\" viewBox=\"0 0 760 424\" role=\"img\" aria-label=\"One Cloudflare worker connects the kiosk, the dashboard and every sale\"><defs><marker id=\"dg-a\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path class=\"dg-head\" d=\"M0 0L10 5L0 10z\"/></marker></defs><text class=\"dg-title\" x=\"24\" y=\"30\">One Cloudflare worker connects the kiosk, the dashboard and every sale</text><path class=\"dg-edge\" d=\"M104 104V144\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M104 200V240\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M288 104V144\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M288 200V240\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M472 104V144\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M472 200V240\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M656 104V144\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M656 200V240\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M104 304V344\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M288 304V344\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M472 304V344\" marker-end=\"url(#dg-a)\"/><path class=\"dg-edge\" d=\"M736 172H748V372H738\" marker-end=\"url(#dg-a)\"/><text class=\"dg-s dg-end\" x=\"742\" y=\"232\">pays</text><rect class=\"dg-person\" x=\"24\" y=\"56\" width=\"160\" height=\"48\" rx=\"3\"/><text class=\"dg-t\" x=\"36\" y=\"76\">Hotel guest</text><text class=\"dg-s\" x=\"36\" y=\"93\">taps the lobby kiosk</text><rect class=\"dg-person\" x=\"208\" y=\"56\" width=\"160\" height=\"48\" rx=\"3\"/><text class=\"dg-t\" x=\"220\" y=\"76\">Guest's phone</text><text class=\"dg-s\" x=\"220\" y=\"93\">scans a QR code</text><rect class=\"dg-person\" x=\"392\" y=\"56\" width=\"160\" height=\"48\" rx=\"3\"/><text class=\"dg-t\" x=\"404\" y=\"76\">You and staff</text><text class=\"dg-s\" x=\"404\" y=\"93\">edit and publish</text><rect class=\"dg-person\" x=\"576\" y=\"56\" width=\"160\" height=\"48\" rx=\"3\"/><text class=\"dg-t\" x=\"588\" y=\"76\">Advertiser</text><text class=\"dg-s\" x=\"588\" y=\"93\">orders and pays</text><rect class=\"dg-box\" x=\"24\" y=\"144\" width=\"160\" height=\"56\" rx=\"3\"/><text class=\"dg-t\" x=\"36\" y=\"166\">Kiosk screen</text><text class=\"dg-s\" x=\"36\" y=\"184\">GitHub Pages</text><rect class=\"dg-box\" x=\"208\" y=\"144\" width=\"160\" height=\"56\" rx=\"3\"/><text class=\"dg-t\" x=\"220\" y=\"166\">QR link</text><text class=\"dg-s\" x=\"220\" y=\"184\">counted, then forwarded</text><rect class=\"dg-box\" x=\"392\" y=\"144\" width=\"160\" height=\"56\" rx=\"3\"/><text class=\"dg-t\" x=\"404\" y=\"166\">Owner dashboard</text><text class=\"dg-s\" x=\"404\" y=\"184\">Cloudflare, /admin</text><rect class=\"dg-box\" x=\"576\" y=\"144\" width=\"160\" height=\"56\" rx=\"3\"/><text class=\"dg-t\" x=\"588\" y=\"166\">Website checkout</text><text class=\"dg-s\" x=\"588\" y=\"184\">order and e-signature</text><rect class=\"dg-core\" x=\"24\" y=\"240\" width=\"528\" height=\"64\" rx=\"3\"/><text class=\"dg-t\" x=\"36\" y=\"264\">Cloudflare worker: spotlight-kiosks</text><text class=\"dg-s dg-ink\" x=\"36\" y=\"282\">Sends kiosks their content, counts every view and scan, answers</text><text class=\"dg-s dg-ink\" x=\"36\" y=\"297\">guest questions, runs this dashboard and advertisers' live reports</text><rect class=\"dg-box\" x=\"576\" y=\"240\" width=\"160\" height=\"64\" rx=\"3\"/><text class=\"dg-t\" x=\"588\" y=\"264\">FormSubmit</text><text class=\"dg-s\" x=\"588\" y=\"282\">emails each order</text><text class=\"dg-s\" x=\"588\" y=\"297\">to your Gmail</text><rect class=\"dg-box\" x=\"24\" y=\"344\" width=\"160\" height=\"56\" rx=\"3\"/><text class=\"dg-t\" x=\"36\" y=\"366\">D1 database</text><text class=\"dg-s\" x=\"36\" y=\"384\">content, counts, deals</text><rect class=\"dg-box\" x=\"208\" y=\"344\" width=\"160\" height=\"56\" rx=\"3\"/><text class=\"dg-t\" x=\"220\" y=\"366\">Workers AI</text><text class=\"dg-s\" x=\"220\" y=\"384\">concierge answers</text><rect class=\"dg-box\" x=\"392\" y=\"344\" width=\"160\" height=\"56\" rx=\"3\"/><text class=\"dg-t\" x=\"404\" y=\"366\">Google Maps</text><text class=\"dg-s\" x=\"404\" y=\"384\">and advertiser sites</text><rect class=\"dg-warn\" x=\"576\" y=\"344\" width=\"160\" height=\"56\" rx=\"3\"/><text class=\"dg-t\" x=\"588\" y=\"366\">Stripe</text><text class=\"dg-s\" x=\"588\" y=\"384\">links not set up yet</text></svg></div>\n<p class=\"fnote\">The kiosk also pulls weather straight from weather.gov. Code lives on GitHub; every change rebuilds the kiosk screen, the website and the worker automatically.</p>\n\n<h2>What happens, step by step</h2>\n<div class=\"flows\">\n<div class=\"flow\"><h3>A guest uses the kiosk</h3><ol>\n<li>The lobby screen opens the kiosk page from GitHub Pages.</li>\n<li>It loads the latest content from the worker and keeps a copy, so it still works if the internet drops.</li>\n<li>Weather comes from weather.gov; questions go to the worker, which asks Workers AI.</li>\n<li>Once a minute the kiosk sends its counts to the worker, which saves them in the database.</li>\n</ol></div>\n<div class=\"flow\"><h3>A guest scans a QR code</h3><ol>\n<li>The phone opens a short CityPulse link on the worker.</li>\n<li>The worker counts the scan for that business or place.</li>\n<li>It forwards the phone to Google Maps, the advertiser's website or the phone guide.</li>\n</ol></div>\n<div class=\"flow\"><h3>You change something</h3><ol>\n<li>Edit hotel info, places, answers or ads here.</li>\n<li>Publish. The worker saves a new version, so any version can be restored.</li>\n<li>Every kiosk checks in every 2 minutes and switches when nobody is using it.</li>\n</ol></div>\n<div class=\"flow\"><h3>An advertiser orders</h3><ol>\n<li>They complete the website checkout and sign the Advertiser Agreement.</li>\n<li>FormSubmit emails the order and their files to Gmail; Stripe takes payment once connected.</li>\n<li>You add the ad here, publish, and send them their live report link.</li>\n</ol></div>\n</div>\n\n<h2>Outside services</h2>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>Service</th><th>What it does for CityPulse</th><th>Status</th><th>Cost</th></tr></thead>\n<tbody>\n<tr><td>Cloudflare Workers</td><td>Runs the worker: kiosk content, counts, QR links, AI answers, this dashboard, reports, Sales Studio</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free plan</td></tr>\n<tr><td>Cloudflare D1</td><td>The database: content, versions, counts, kiosks, deals, notes, tasks</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free plan</td></tr>\n<tr><td>Workers AI (Gemma 4)</td><td>Writes the concierge's answers from the hotel's approved facts</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free daily allowance</td></tr>\n<tr><td>GitHub and GitHub Pages</td><td>Stores the code; hosts the kiosk screen, phone guide and website</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free</td></tr>\n<tr><td>Weather.gov</td><td>Current weather and 7-day forecast on the kiosk</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free, no account</td></tr>\n<tr><td>Google Maps</td><td>Walking directions and evening routes opened by QR codes</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free, links only</td></tr>\n<tr><td>FormSubmit</td><td>Emails website orders and inquiries to Gmail</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free</td></tr>\n<tr><td>Gmail</td><td>Receives orders and leads today</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free</td></tr>\n<tr><td>Google Fonts</td><td>Typefaces on the website</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Free</td></tr>\n<tr><td>Elo touchscreen</td><td>The lobby kiosk at Lexen North Hollywood</td><td><span class=\"pill ok\"><i></i>Live</span></td><td>Hardware, one-time</td></tr>\n<tr><td>Stripe Payment Links</td><td>Online payment for ad packages</td><td><span class=\"pill warn\"><i></i>Setting up</span></td><td>Per-payment fee</td></tr>\n<tr><td>Google Workspace</td><td>sales@ and support@citypulsekiosks.com; Gmail sending in Sales Studio</td><td><span class=\"pill warn\"><i></i>Setting up</span></td><td>Per user, monthly</td></tr>\n<tr><td>Twilio</td><td>Calls and texts from Sales Studio</td><td><span class=\"pill off\"><i></i>Ready to connect</span></td><td>Number plus usage</td></tr>\n<tr><td>WordPress</td><td>WordPress version of the website, handed to a developer</td><td><span class=\"pill off\"><i></i>Handed off</span></td><td>Depends on host</td></tr>\n<tr><td>Claude (Anthropic)</td><td>Optional stronger concierge model</td><td><span class=\"pill off\"><i></i>Optional</span></td><td>Pay per use</td></tr>\n<tr><td>T-Mobile 4G</td><td>A data card per kiosk, so screens stay online without venue Wi-Fi</td><td><span class=\"pill off\"><i></i>Planned</span></td><td>Per kiosk, monthly</td></tr>\n</tbody></table></div>\n"},{"id":"dashboard","title":"Dashboard guide","summary":"Signing in, publishing, what each section does and resetting the password.","icon":"kiosks","updated":"2026-10-09","html":"<p class=\"lead\">This dashboard has no username: one staff password opens it, on any laptop or phone. Bookmark <b>spotlight-kiosks.sarvesh-bb0.workers.dev/admin</b>.</p>\n\n<h2>Signing in and publishing</h2>\n<ol class=\"steps\">\n<li>Open the dashboard link, type the staff password and click <b>Sign in</b>. Sessions last 12 hours.</li>\n<li>Make changes in any section. A bar appears at the bottom: you have unpublished changes.</li>\n<li>Click <b>Publish to kiosks</b>. Every kiosk switches to the new version within about 2 minutes, when no guest is using it.</li>\n<li>To make it happen at once, open <b>Kiosks</b> and click <b>Restart</b>.</li>\n<li>Click <b>Sign out</b> in the sidebar when you are done on a shared computer.</li>\n</ol>\n<p>Press <b>Ctrl+K</b> (<b>&#8984;K</b> on a Mac) anywhere to jump to a page, place, advertiser or action.</p>\n\n<h2>What each section does</h2>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>Section</th><th>What you do there</th></tr></thead>\n<tbody>\n<tr><td>Overview</td><td>Guest sessions, ad views, QR scans, ad revenue, next best actions, busiest hours, notes</td></tr>\n<tr><td>Ads</td><td>Add or edit advertisers: logo, tagline, website, QR link, campaign dates, private deal details, live report link</td></tr>\n<tr><td>Places</td><td>Restaurants, coffee, things to do and hotel services; the AI concierge only recommends these</td></tr>\n<tr><td>Answers</td><td>Approved answers to common questions, matched by keywords</td></tr>\n<tr><td>Announcements</td><td>Short notices on the welcome and home screens, with start and end dates</td></tr>\n<tr><td>Notes</td><td>Shared sticky notes and to-dos for the team</td></tr>\n<tr><td>Files</td><td>These guides and the launch checklist</td></tr>\n<tr><td>Hotel</td><td>Hotel name, phone, email, address, logo and background photos</td></tr>\n<tr><td>Kiosks</td><td>Each screen's status, last check-in and version; Restart or Remove</td></tr>\n<tr><td>History</td><td>Every published version; restore any of them in one click</td></tr>\n</tbody></table></div>\n\n<h2>Password and recovery codes</h2>\n<p>Open <b>Password &amp; security</b> at the bottom of the sidebar.</p>\n<ul>\n<li><b>Change password:</b> type the current one and the new one (at least 10 characters). Everyone else is signed out.</li>\n<li><b>Recovery codes:</b> create a set of 8 and print them or keep them in a password manager. Each code resets the password once.</li>\n</ul>\n\n<h2>Forgot the password</h2>\n<ol class=\"steps\">\n<li>On the sign-in screen, click <b>Forgot password?</b></li>\n<li>Enter one of your recovery codes and a new password, then click <b>Reset and sign in</b>.</li>\n</ol>\n<h2>Sales Studio passwords</h2>\n<p>Sales Studio has its own logins. Anyone can click <b>Forgot password?</b> on its sign-in screen; the request appears under <b>Password &amp; security &rarr; Sales Studio logins</b> here and in Next best actions. Click <b>Reset password</b>, confirm with your dashboard password, and give them the temporary password shown. They pick their own at sign-in. This works for the Sales Studio owner login too.</p>\n<p>No dashboard recovery codes left? The account owner resets it in Cloudflare: Workers &amp; Pages &rarr; spotlight-kiosks &rarr; Settings &rarr; Variables and Secrets &rarr; edit <b>ADMIN_PASSWORD</b> &rarr; Rotate &rarr; Deploy. That password then signs in, and the old password and codes stop working.</p>\n<div class=\"callout\">Changing the password in the dashboard keeps advertisers' report links working. Changing ADMIN_PASSWORD in Cloudflare turns them off, so send new links from Ads &rarr; Advertiser report.</div>\n\n<h2>Adding a new kiosk</h2>\n<p>On the new screen, open the kiosk link once with a name on the end, for example <b>&hellip;/kiosk-app/?kiosk=lobby-2</b>. It appears under Kiosks within 2 minutes and keeps that name.</p>\n"},{"id":"qa","title":"QA report, Oct 9","summary":"What was tested before launch and the results.","icon":"check","updated":"2026-10-09","html":"<p class=\"lead\">Every guest, staff and customer path passed on Oct 9; the open issues are setup items, not bugs. Checks marked live ran on the real site; the rest ran on an exact test copy so no fake numbers reached the reports.</p>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>Area</th><th>What was checked</th><th>Result</th></tr></thead>\n<tbody>\n<tr><td>Lobby kiosk</td><td>Check-in, version, screen size (live)</td><td><span class=\"pill ok\"><i></i>Pass</span> version 17, 1080 &times; 1920</td></tr>\n<tr><td>Kiosk screen</td><td>Latest version, content from the server, weather, ads (live)</td><td><span class=\"pill ok\"><i></i>Pass</span> 12 home tiles, 7-day forecast, 3 ads</td></tr>\n<tr><td>AI concierge</td><td>Asked for a late dinner nearby (live)</td><td><span class=\"pill ok\"><i></i>Pass</span> recommended Granville and NoHo Pizza with walking times</td></tr>\n<tr><td>Guest walkthrough</td><td>Every section, place pages, keyboard, take-home QR, map, Plan my evening, upright and sideways</td><td><span class=\"pill ok\"><i></i>Pass</span></td></tr>\n<tr><td>Accessibility</td><td>Larger text, high contrast, lower the screen, stop motion, read aloud</td><td><span class=\"pill ok\"><i></i>Pass</span> after fixes on Oct 9</td></tr>\n<tr><td>Idle and reset</td><td>Warning, \"stay\", return to welcome, rapid taps</td><td><span class=\"pill ok\"><i></i>Pass</span></td></tr>\n<tr><td>Dashboard</td><td>Sign-in, database, stats (live); every page on desktop, tablet and phone</td><td><span class=\"pill ok\"><i></i>Pass</span> 0 contrast failures, 0 cut-off text</td></tr>\n<tr><td>Publishing</td><td>Edit, publish, restore, notes, search</td><td><span class=\"pill ok\"><i></i>Pass</span></td></tr>\n<tr><td>Advertiser report</td><td>On screen, printed and as PDF</td><td><span class=\"pill ok\"><i></i>Pass</span> prints white with the logo</td></tr>\n<tr><td>Website</td><td>All 205 pages crawled; 29 key pages checked live</td><td><span class=\"pill ok\"><i></i>Pass</span> 0 broken links, 0 script errors</td></tr>\n<tr><td>Checkout</td><td>Four steps through to a placed order</td><td><span class=\"pill ok\"><i></i>Pass</span> order, number and signature sent</td></tr>\n<tr><td>Sales Studio</td><td>Loads at /sales (live)</td><td><span class=\"pill ok\"><i></i>Pass</span></td></tr>\n</tbody></table></div>\n<h2>Numbers at launch</h2>\n<p>Last 30 days, including testing: 21 guest sessions, 4,839 ad plays, 205 ad views with a guest present, 45 guests reached, 7 questions asked, 2 QR scans. They prove the tracking works; use real guest numbers in pitches once a full week is in.</p>\n<h2>Open setup items</h2>\n<ul>\n<li>Stripe Payment Links not connected yet.</li>\n<li>FormSubmit activation for order emails not confirmed.</li>\n<li>sales@citypulsekiosks.com not set up.</li>\n<li>Attorney review of the Terms and Advertiser Agreement.</li>\n</ul>\n"},{"id":"links","title":"Links and accounts","summary":"Every address and the account that manages it. No passwords.","icon":"link","updated":"2026-10-09","html":"<p class=\"lead\">Everything runs on accounts CityPulse owns. No passwords are written here.</p>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>What</th><th>Address</th><th>Managed in</th></tr></thead>\n<tbody>\n<tr><td>Owner dashboard</td><td><a href=\"/admin\">spotlight-kiosks.sarvesh-bb0.workers.dev/admin</a></td><td>Staff password, Cloudflare secret ADMIN_PASSWORD</td></tr>\n<tr><td>Sales Studio</td><td><a href=\"/sales\" target=\"_blank\" rel=\"noopener\">spotlight-kiosks.sarvesh-bb0.workers.dev/sales</a></td><td>Owner login; the owner issues every rep login</td></tr>\n<tr><td>Kiosk screen</td><td><a href=\"https://aeroassistindustries.github.io/spotlight-kiosks/kiosk-app/\" target=\"_blank\" rel=\"noopener\">aeroassistindustries.github.io/spotlight-kiosks/kiosk-app/</a></td><td>No sign-in; add ?kiosk=name once on a new screen</td></tr>\n<tr><td>Website</td><td><a href=\"https://aeroassistindustries.github.io/spotlight-kiosks/\" target=\"_blank\" rel=\"noopener\">aeroassistindustries.github.io/spotlight-kiosks</a></td><td>GitHub, AeroAssistIndustries</td></tr>\n<tr><td>Pricing and checkout</td><td><a href=\"https://aeroassistindustries.github.io/spotlight-kiosks/pricing/\" target=\"_blank\" rel=\"noopener\">&hellip;/pricing/</a></td><td>Orders email sarvesh.joshiaz@gmail.com</td></tr>\n<tr><td>Server, database, AI</td><td>Cloudflare &rarr; Workers &amp; Pages &rarr; spotlight-kiosks</td><td>Cloudflare account</td></tr>\n<tr><td>Code</td><td><a href=\"https://github.com/AeroAssistIndustries/spotlight-kiosks\" target=\"_blank\" rel=\"noopener\">github.com/AeroAssistIndustries/spotlight-kiosks</a></td><td>GitHub</td></tr>\n<tr><td>Payment and order-email settings</td><td>assets/config.js in the code</td><td>GitHub</td></tr>\n</tbody></table></div>\n\n<h2>Keys stored on the server</h2>\n<p>Set in Cloudflare &rarr; spotlight-kiosks &rarr; Settings &rarr; Variables and Secrets. Names only.</p>\n<div class=\"table-wrap\"><table>\n<thead><tr><th>Key</th><th>Used for</th><th>Status</th></tr></thead>\n<tbody>\n<tr><td>ADMIN_PASSWORD</td><td>Dashboard sign-in and advertiser report links</td><td><span class=\"pill ok\"><i></i>Set</span></td></tr>\n<tr><td>SALES_SECRET</td><td>Sales Studio sign-ins</td><td><span class=\"pill off\"><i></i>Optional</span></td></tr>\n<tr><td>TWILIO_* (5 keys)</td><td>Calls and texts from Sales Studio</td><td><span class=\"pill off\"><i></i>When needed</span></td></tr>\n<tr><td>GOOGLE_CLIENT_ID / SECRET</td><td>Sending email from Gmail in Sales Studio</td><td><span class=\"pill off\"><i></i>When needed</span></td></tr>\n<tr><td>ANTHROPIC_API_KEY</td><td>A stronger AI concierge (Claude) in place of the free model</td><td><span class=\"pill off\"><i></i>Optional</span></td></tr>\n</tbody></table></div>\n"}];
